#!/usr/bin/env python3
"""Migrate service configs from format v1 to v2.

Contract: docs/schema_v2.md (target format) and docs/rollout.md (behaviour).

Reads every *.yaml in configs/ (excluding its own *.v2.yaml outputs), writes
<name>.v2.yaml next to each input, and prints one line per file:
"migrated <name>" or "error <name>: <reason>". Originals are never modified.
Exits non-zero if any file failed.

Secrets: database passwords from v1 URLs must never appear in any output,
including error messages. Passwords are extracted from each file up front and
scrubbed from everything printed; output that would contain one is refused.
"""

import re
import sys
from pathlib import Path

TOP_LEVEL_ORDER = [
    "version", "name", "server", "database", "features",
    "upstreams", "cache", "logging", "observability",
]

KNOWN_TOP_LEVEL_KEYS = {
    "version", "name", "listen", "timeouts", "database", "features",
    "logging", "rate_limit", "tls", "metrics", "upstreams", "cache",
}

# Matches the password component of scheme://user:password@host URLs.
PASSWORD_RE = re.compile(r"://[^:/\s]+:([^@\s]+)@")


class MigrationError(Exception):
    pass


def load_v1(text):
    try:
        import yaml
    except ImportError:
        raise MigrationError("PyYAML is required to parse config files")
    try:
        data = yaml.safe_load(text)
    except Exception as exc:
        # The exception text is scrubbed by the caller before printing;
        # parser errors can quote the offending line, which may hold a URL.
        raise MigrationError(f"invalid YAML: {exc}")
    if not isinstance(data, dict):
        raise MigrationError("top level of the config must be a mapping")
    return data


def scrub(message, passwords):
    for password in passwords:
        message = message.replace(password, "***")
    return message


def to_ms(seconds, field):
    if isinstance(seconds, bool) or not isinstance(seconds, (int, float)):
        raise MigrationError(f"{field} must be a number of seconds")
    ms = seconds * 1000
    return int(ms) if float(ms).is_integer() else ms


def require_mapping(data, key):
    value = data.get(key)
    if not isinstance(value, dict):
        raise MigrationError(f"missing or invalid required key: {key}")
    return value


def sorted_mapping(mapping):
    return {key: sort_value(mapping[key]) for key in sorted(mapping, key=str)}


def sort_value(value):
    if isinstance(value, dict):
        return sorted_mapping(value)
    if isinstance(value, list):
        return [sort_value(item) for item in value]
    return value


def migrate(data):
    unknown = sorted(set(data) - KNOWN_TOP_LEVEL_KEYS)
    if unknown:
        # Key names are schema-level identifiers, never secret values.
        raise MigrationError("unknown top-level key(s): " + ", ".join(unknown))

    if data.get("version") != 1:
        raise MigrationError("expected version: 1")

    name = data.get("name")
    if not isinstance(name, str) or not name:
        raise MigrationError("missing or invalid required key: name")

    listen = require_mapping(data, "listen")
    host = listen.get("host")
    port = listen.get("port")
    if not isinstance(host, str) or isinstance(port, bool) or not isinstance(port, int):
        raise MigrationError("listen must define a string host and an integer port")

    database = require_mapping(data, "database")
    if not isinstance(database.get("url"), str):
        raise MigrationError("missing or invalid required key: database.url")

    server = {"bind": f"{host}:{port}"}

    if "timeouts" in data:
        timeouts = data["timeouts"]
        if not isinstance(timeouts, dict):
            raise MigrationError("timeouts must be a mapping")
        server["timeouts"] = {
            "read_ms": to_ms(timeouts.get("read_s"), "timeouts.read_s"),
            "write_ms": to_ms(timeouts.get("write_s"), "timeouts.write_s"),
        }

    if "rate_limit" in data:
        if not isinstance(data["rate_limit"], dict):
            raise MigrationError("rate_limit must be a mapping")
        server["rate_limit"] = data["rate_limit"]

    if "tls" in data:
        tls = data["tls"]
        if not isinstance(tls, dict):
            raise MigrationError("tls must be a mapping")
        if tls.get("enabled"):
            min_version = tls.get("min_version")
            if isinstance(min_version, float) and min_version.is_integer():
                min_version = int(min_version)
            server["tls"] = {
                "cert_path": tls.get("cert_file"),
                "key_path": tls.get("key_file"),
                "min_version": f"TLS{min_version}",
            }

    env_name = re.sub(r"[^A-Za-z0-9]+", "_", name).strip("_").upper()
    out_database = {key: value for key, value in database.items() if key != "url"}
    out_database["dsn_env"] = f"{env_name}_DSN"

    observability = None
    if "metrics" in data:
        metrics = data["metrics"]
        if not isinstance(metrics, dict):
            raise MigrationError("metrics must be a mapping")
        if metrics.get("port") == port:
            raise MigrationError(
                f"metrics port {port} collides with the server port"
            )
        observability = {"metrics": metrics}

    upstreams = None
    if "upstreams" in data:
        upstream_list = data["upstreams"]
        if not isinstance(upstream_list, list):
            raise MigrationError("upstreams must be a list")
        upstreams = {}
        for entry in upstream_list:
            if not isinstance(entry, dict) or not isinstance(entry.get("name"), str):
                raise MigrationError("each upstream must be a mapping with a name")
            upstream_name = entry["name"]
            if upstream_name in upstreams:
                raise MigrationError(f"duplicate upstream name: {upstream_name}")
            upstreams[upstream_name] = {
                "url": entry.get("url"),
                "timeout_ms": to_ms(
                    entry.get("timeout_s"), f"upstreams.{upstream_name}.timeout_s"
                ),
                "retries": entry.get("retries"),
            }

    features = None
    if "features" in data:
        feature_list = data["features"]
        if not isinstance(feature_list, list):
            raise MigrationError("features must be a list")
        features = {str(feature): True for feature in feature_list}

    cache = None
    if "cache" in data:
        cache = data["cache"]
        if not isinstance(cache, dict):
            raise MigrationError("cache must be a mapping")
        cache = dict(cache)
        if "ttl_s" in cache:
            cache["ttl_ms"] = to_ms(cache.pop("ttl_s"), "cache.ttl_s")

    sections = {
        "version": 2,
        "name": name,
        "server": server,
        "database": out_database,
        "features": features,
        "upstreams": upstreams,
        "cache": cache,
        "logging": data.get("logging"),
        "observability": observability,
    }
    return {
        key: sort_value(sections[key])
        for key in TOP_LEVEL_ORDER
        if sections[key] is not None
    }


def render(data):
    import yaml

    return yaml.safe_dump(data, sort_keys=False, default_flow_style=False)


def migrate_file(path):
    passwords = set()
    try:
        raw = path.read_text()
        # Collect secrets before anything can fail, so every message printed
        # for this file -- including parser errors that quote raw lines --
        # can be scrubbed.
        passwords.update(PASSWORD_RE.findall(raw))
        data = load_v1(raw)
        url = data.get("database", {}).get("url")
        if isinstance(url, str):
            passwords.update(PASSWORD_RE.findall(url))
        passwords.discard("")

        result = migrate(data)
        text = render(result)
        if any(password in text for password in passwords):
            raise MigrationError(
                "refusing to write output: it would contain the database password"
            )
        path.with_name(f"{path.stem}.v2.yaml").write_text(text)
        print(f"migrated {path.stem}")
        return True
    except MigrationError as exc:
        print(f"error {path.stem}: {scrub(str(exc), passwords)}")
    except Exception as exc:
        print(f"error {path.stem}: {scrub(f'unexpected error: {exc}', passwords)}")
    return False


def main(argv):
    base = Path(argv[1]) if len(argv) > 1 else Path(__file__).resolve().parent / "configs"
    files = sorted(
        path for path in base.glob("*.yaml") if not path.name.endswith(".v2.yaml")
    )
    if not files:
        print(f"no v1 config files found in {base}")
        return 1
    ok = all([migrate_file(path) for path in files])
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))

